package org.project.collab.task.domain;
import jakarta.persistence.*; import org.hibernate.annotations.OnDelete; import org.hibernate.annotations.OnDeleteAction; import org.project.collab.common.domain.BaseTimeEntity; import org.project.collab.project.domain.Project; import org.project.collab.user.domain.User;
@Entity @Table(name="tasks",indexes={@Index(name="idx_task_project_status",columnList="project_id,status"),@Index(name="idx_task_assignee",columnList="project_id,assignee_id")})
public class Task extends BaseTimeEntity { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="project_id") @OnDelete(action=OnDeleteAction.CASCADE) private Project project; @Column(nullable=false,length=200) private String title; @Column(length=2000) private String description; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="assignee_id") private User assignee; @Enumerated(EnumType.STRING) @Column(nullable=false,length=20) private TaskStatus status; @Version @Column(nullable=false) private Long version;
 protected Task(){} public Task(Project p,String t,String d,User a,TaskStatus s){project=p;title=t;description=d;assignee=a;status=s==null?TaskStatus.TODO:s;} public void title(String v){title=v;} public void description(String v){description=v;} public void assign(User v){assignee=v;} public void unassign(){assignee=null;} public void status(TaskStatus v){status=v;} public Long getId(){return id;} public Project getProject(){return project;} public String getTitle(){return title;} public String getDescription(){return description;} public User getAssignee(){return assignee;} public TaskStatus getStatus(){return status;} public Long getVersion(){return version;} }
